import CryptoKit
import Foundation
import Testing
@testable import FantasyMapCore

/// Compatibility fixtures for saved maps at format version 1 and algorithm revision 1 (see docs/steps/08-saving-and-loading.md).
///
/// The files in `Fixtures/revision1` are **fixed**: committed once and never regenerated by these tests, so a change that
/// alters the rebuilt cells, the saved format or the loaded state fails here even if generating and loading changed alike. The
/// manifest holds, for each file, the digest of its bytes and of the geometry rebuilt from it. Where the grid is one the
/// original's own `Grid.generate` was captured for, the expected cell-structure digest is the **original's**.
///
/// To write them (only deliberately, with an algorithm revision bump explained in the commit):
/// `MAP_WRITE_REVISION1=<folder> swift test --filter RevisionOneFixtureTests/writeTheFixtures`
struct RevisionOneFixtureTests {
	struct Entry: Codable {
		var file: String
		var fileSha256: String
		var seed: String
		var width: Double
		var height: Double
		var cellsDesired: Int
		var template: String
		var elevationLimit: Double
		var cells: Int
		var features: Int
		var hasRetainedOpenedLakeRecord: Bool
		var coastStateIsNotWhatAFreshMarkingGives: Bool
		var cellStructureSha256: String
		var vertexPointsSha256: String
		var heightsSha256: String
		var featureIdsSha256: String
		var originalCellStructureSha256: String?
	}
	struct Manifest: Codable { var formatVersion: Int; var algorithmRevision: Int; var entries: [Entry] }

	static let wanted: [(seed: String, width: Double, height: Double, cells: Int, template: String, limit: Double)] = [
		("kaz-1", 1280, 800, 10_000, "highIsland", 20), // the original's default map
		("\u{00E9}", 1280, 800, 1_000, "highIsland", 5),
		("wide", 1000, 90, 300, "highIsland", 20)
	]

	static func sha(_ data: Data) -> String { SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined() }

	static func json(_ x: [[Int]]) -> String { "[" + x.map { "[" + $0.map(String.init).joined(separator: ",") + "]" }.joined(separator: ",") + "]" }
	static func json(_ x: [Int]) -> String { "[" + x.map(String.init).joined(separator: ",") + "]" }

	/// The digest of the integer structure of the cells and vertices, as the original-capture script hashes it.
	static func cellStructureDigest(_ v: VoronoiDiagram) -> String {
		let text = "[" + [json(v.cells.c), json(v.cells.v), json(v.cells.b), json(v.vertices.v), json(v.vertices.c)].joined(separator: ",") + "]"
		return sha(Data(text.utf8))
	}

	static func vertexDigest(_ v: VoronoiDiagram) -> String {
		var bytes = Data()
		for p in v.vertices.p {
			withUnsafeBytes(of: p.x.bitPattern.littleEndian) { bytes.append(contentsOf: $0) }
			withUnsafeBytes(of: p.y.bitPattern.littleEndian) { bytes.append(contentsOf: $0) }
		}
		return sha(bytes)
	}

	static func idDigest(_ ids: [UInt16]) -> String {
		var bytes = Data()
		for id in ids { bytes.append(UInt8(id & 0xff)); bytes.append(UInt8(id >> 8)) }
		return sha(bytes)
	}

	static func folder() throws -> URL {
		try #require(Bundle.module.url(forResource: "Fixtures/revision1", withExtension: nil))
	}

	// MARK: writing (deliberate, never part of a normal run)

	@Test(.enabled(if: ProcessInfo.processInfo.environment["MAP_WRITE_REVISION1"] != nil))
	func writeTheFixtures() throws {
		let out = URL(filePath: try #require(ProcessInfo.processInfo.environment["MAP_WRITE_REVISION1"]))
		struct OriginalGrids: Decodable { struct G: Decodable { var seed: String; var width: Double; var height: Double; var cellsDesired: Int; var cellStructureSha256: String }; var grids: [G] }
		let originals = try JSONDecoder().decode(OriginalGrids.self, from: Fixtures.data("grid-original")).grids
		var entries: [Entry] = []
		for w in Self.wanted {
			let template = try #require(HeightmapTemplate.named(w.template))
			let map = try LandMap.generate(seed: w.seed, width: w.width, height: w.height, cellsDesired: w.cells, template: template, elevationLimit: w.limit)
			let data = try map.encoded()
			let name = "map-\(w.template)-\(w.cells)-limit\(Int(w.limit)).json"
			try data.write(to: out.appending(path: name))
			let fresh = try LandFeatures.markup(heights: map.heights, voronoi: map.voronoi)
			let original = originals.first { $0.seed == w.seed && $0.width == w.width && $0.height == w.height && $0.cellsDesired == w.cells }
			entries.append(Entry(
				file: name, fileSha256: Self.sha(data), seed: w.seed, width: w.width, height: w.height, cellsDesired: w.cells, template: w.template,
				elevationLimit: w.limit, cells: map.heights.count, features: map.features.features.count,
				hasRetainedOpenedLakeRecord: map.features.features.contains { $0.kind == .ocean && !$0.border },
				coastStateIsNotWhatAFreshMarkingGives: fresh != map.features,
				cellStructureSha256: Self.cellStructureDigest(map.voronoi), vertexPointsSha256: Self.vertexDigest(map.voronoi),
				heightsSha256: Self.sha(Data(map.heights)), featureIdsSha256: Self.idDigest(map.features.featureIds),
				originalCellStructureSha256: original?.cellStructureSha256
			))
		}
		let encoder = JSONEncoder()
		encoder.outputFormatting = [.sortedKeys, .prettyPrinted]
		try encoder.encode(Manifest(formatVersion: FantasyMapCore.formatVersion, algorithmRevision: FantasyMapCore.algorithmRevision, entries: entries)).write(to: out.appending(path: "manifest.json"))
	}

	// MARK: the guard

	@Test func theFixedRevisionOneFilesStillLoadToTheSameStateAndTheSameRebuiltGeometry() throws {
		let folder = try Self.folder()
		let manifest = try JSONDecoder().decode(Manifest.self, from: Data(contentsOf: folder.appending(path: "manifest.json")))
		#expect(manifest.formatVersion == 1 && manifest.algorithmRevision == 1)
		// a change to format version or revision must be deliberate: the fixtures are for revision 1
		#expect(FantasyMapCore.formatVersion == manifest.formatVersion && FantasyMapCore.algorithmRevision == manifest.algorithmRevision, "the format or revision changed: keep revision-1 files readable (or retain the old rebuild) and add fixtures for the new one")
		#expect(manifest.entries.count == Self.wanted.count)
		var originalChecked = 0, retained = 0, nonCanonical = 0
		for entry in manifest.entries {
			let data = try Data(contentsOf: folder.appending(path: entry.file))
			#expect(Self.sha(data) == entry.fileSha256, "\(entry.file): the committed file itself is unchanged")
			let map = try LandMap(decoding: data)
			// the loaded state is the saved state, and saving it again gives the same bytes
			#expect(try map.encoded() == data, "\(entry.file): re-saving gives the same bytes")
			#expect(map.heights.count == entry.cells && map.features.features.count == entry.features, "\(entry.file): counts")
			#expect(Self.sha(Data(map.heights)) == entry.heightsSha256, "\(entry.file): heights")
			#expect(Self.idDigest(map.features.featureIds) == entry.featureIdsSha256, "\(entry.file): feature ids")
			// the cells rebuilt from the points
			#expect(Self.cellStructureDigest(map.voronoi) == entry.cellStructureSha256, "\(entry.file): rebuilt cell structure")
			#expect(Self.vertexDigest(map.voronoi) == entry.vertexPointsSha256, "\(entry.file): rebuilt vertex coordinates")
			if let original = entry.originalCellStructureSha256 {
				#expect(Self.cellStructureDigest(map.voronoi) == original, "\(entry.file): the rebuilt cells equal the ORIGINAL's own")
				originalChecked += 1
			}
			// the state these files are meant to preserve
			#expect(map.features.features.contains { $0.kind == .ocean && !$0.border } == entry.hasRetainedOpenedLakeRecord)
			let fresh = try LandFeatures.markup(heights: map.heights, voronoi: map.voronoi)
			#expect((fresh != map.features) == entry.coastStateIsNotWhatAFreshMarkingGives)
			if entry.hasRetainedOpenedLakeRecord { retained += 1 }
			if entry.coastStateIsNotWhatAFreshMarkingGives { nonCanonical += 1 }
		}
		#expect(retained == Self.wanted.count && nonCanonical == Self.wanted.count, "every fixture carries an opened lake's retained record and non-canonical state")
		#expect(originalChecked == Self.wanted.count, "every fixture's grid is one the original's own cells were captured for")
	}
}
